<?php
// Direct test of receipt logic
require_once __DIR__ . '/db_connect.php';  $id = $_GET['id'] ?? 'MERCH2026125350963';
$type = 'merchandise';  echo "<h2>Direct Receipt Test</h2>";
echo "<p>Testing ID: <strong>$id</strong></p>";
echo "<hr>";  try {  // Try exact match first  $stmt = $pdo->prepare("  SELECT mt.*,  u.name AS staff_name,  s.name AS station_name  FROM merchandise_transactions mt  LEFT JOIN users u ON mt.staff_id = u.id  LEFT JOIN stations s ON mt.station_id = s.id  WHERE mt.transaction_id = ?  LIMIT 1  ");  $stmt->execute([$id]);  $txn = $stmt->fetch(PDO::FETCH_ASSOC);  if ($txn) {  echo "<p style='color:green;'> Transaction found!</p>";  echo "<pre>";  print_r($txn);  echo "</pre>";  // Get items  $stmt2 = $pdo->prepare("  SELECT * FROM merchandise_transaction_items  WHERE transaction_id = ?  ");  $stmt2->execute([$txn['id']]);  $items = $stmt2->fetchAll(PDO::FETCH_ASSOC);  echo "<p>Items found: " . count($items) . "</p>";  echo "<pre>";  print_r($items);  echo "</pre>";  // Try to build sale object  echo "<p>Building sale object...</p>";  $sale = [  'transaction_id' => $txn['transaction_id'],  'id' => $txn['transaction_id'],  'total_amount' => $txn['total_amount'] ?? 0,  'customer_name' => $txn['customer_name'] ?? 'Walk-in',  'items' => $items,  ];  echo "<p style='color:green;'> Sale object built successfully!</p>";  echo "<pre>";  print_r($sale);  echo "</pre>";  echo "<hr>";  echo "<p><a href='receipt.php?id=" . urlencode($id) . "&type=merchandise' target='_blank'>Open Receipt Page</a></p>";  } else {  echo "<p style='color:red;'> Transaction NOT found</p>";  // Try fuzzy match  echo "<p>Trying fuzzy match...</p>";  $stmt = $pdo->prepare("  SELECT transaction_id, customer_name  FROM merchandise_transactions  WHERE transaction_id LIKE ?  LIMIT 5  ");  $stmt->execute([$id . '%']);  $similar = $stmt->fetchAll(PDO::FETCH_ASSOC);  if (count($similar) > 0) {  echo "<p>Found similar transactions:</p><ul>";  foreach ($similar as $s) {  echo "<li>" . $s['transaction_id'] . " - " . $s['customer_name'] . "</li>";  }  echo "</ul>";  }  }  } catch (Exception $e) {  echo "<p style='color:red;'>ERROR: " . htmlspecialchars($e->getMessage()) . "</p>";  echo "<pre>" . htmlspecialchars($e->getTraceAsString()) . "</pre>";
